// Affiliate distribution (精选联盟 分销) read/write paths
// (docs/engineering/WORKBENCH-API.md §11).
//
// Same conventions as the B0 ledgers: workspace-scoped, archived rows hidden,
// keyset paging on the list's sort key where a list can grow, money as
// NUMERIC(14,2).
//
// Four leads, one rule each:
//
//   - `affiliate_product` — the SKU and the commission it pays. Soft deleted, so
//     every read filters `archived_at IS NULL`.
//   - `affiliate_pick` — product × creator, the promotion relationship the
//     platform attributes orders to. Also soft deleted.
//   - `affiliate_daily` — the platform report's day snapshot for one pick. No
//     archive and no delete: the upsert is the only write, and it replaces the
//     day rather than adding a second observation of it.
//   - `affiliate_settlement` — the platform's periodic statement. No delete
//     either; a wrong statement is corrected by update.
//
// Nothing here derives one money column from another. `net_amount` is what the
// platform said, `gmv_amount` and `refund_amount` are reported side by side, and
// the only division in this domain (refund rate) happens in the handler through
// `ratioValue` so the 0–1 scale is applied in exactly one place.
func (q *Queries) ListAffiliateProducts(ctx context.Context, arg ListAffiliateProductsParams) ([]AffiliateProduct, error) {
	rows, err := q.db.Query(ctx, listAffiliateProducts,
		arg.WorkspaceID,
		arg.ClientID,
		arg.Status,
		arg.Platform,
		arg.CursorAt,
		arg.CursorID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AffiliateProduct{}
	for rows.Next() {
		var i AffiliateProduct
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ClientID,
			&i.Platform,
			&i.PlatformProductID,
			&i.Title,
			&i.Category,
			&i.Price,
			&i.Currency,
			&i.CommissionRate,
			&i.Activity,
			&i.Status,
			&i.OwnerMemberID,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ArchivedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listAffiliateSettlements = `-- name: ListAffiliateSettlements :many
SELECT id, workspace_id, period_start, period_end, gross_commission, tech_service_fee, refund_deduction, net_amount, currency, status, paid_at, external_no, note, created_by, created_at, updated_at
FROM affiliate_settlement
WHERE workspace_id = $1
  AND ($2::text IS NULL OR status = $2::text)
  AND ($3::date IS NULL OR period_end >= $3::date)
  AND ($4::date IS NULL OR period_start <= $4::date)
ORDER BY period_start DESC, id DESC
LIMIT $5
`

type ListAffiliateSettlementsParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	Status      pgtype.Text `json:"status"`
	PeriodFrom  pgtype.Date `json:"period_from"`
	PeriodTo    pgtype.Date `json:"period_to"`
	Limit       int32       `json:"limit"`
}

// Newest period first. `period_from` / `period_to` are an overlap window, not a
// containment one: a statement that straddles the boundary of what the reader
// asked for is still a statement about it.
//
// No keyset cursor: a settlement statement is issued once per settlement cycle,
// so one workspace has tens of them, not tens of thousands, and the sort key is
// the period rather than the row's own insertion time.
func (q *Queries) ListAffiliateSettlements(ctx context.Context, arg ListAffiliateSettlementsParams) ([]AffiliateSettlement, error) {
	rows, err := q.db.Query(ctx, listAffiliateSettlements,
		arg.WorkspaceID,
		arg.Status,
		arg.PeriodFrom,
		arg.PeriodTo,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AffiliateSettlement{}
	for rows.Next() {
		var i AffiliateSettlement
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.PeriodStart,
			&i.PeriodEnd,
			&i.GrossCommission,
			&i.TechServiceFee,
			&i.RefundDeduction,
			&i.NetAmount,
			&i.Currency,
			&i.Status,
			&i.PaidAt,
			&i.ExternalNo,
			&i.Note,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

