const upsertAffiliateDaily = `-- name: UpsertAffiliateDaily :one
INSERT INTO affiliate_daily (
    workspace_id, pick_id, stat_date, gmv_amount, order_count, refund_amount,
    est_commission, settled_commission, currency, created_by
) VALUES (
    $1, $2, $3,
    $4::numeric, $5, $6::numeric,
    $7::numeric, $8::numeric,
    $9, $10::uuid
)
ON CONFLICT (workspace_id, pick_id, stat_date)
DO UPDATE SET
    gmv_amount = excluded.gmv_amount,
    order_count = excluded.order_count,
    refund_amount = excluded.refund_amount,
    est_commission = excluded.est_commission,
    settled_commission = excluded.settled_commission,
    currency = excluded.currency,
    updated_at = now()
RETURNING id, workspace_id, pick_id, stat_date, gmv_amount, order_count, refund_amount, est_commission, settled_commission, currency, created_by, created_at, updated_at
`

type UpsertAffiliateDailyParams struct {
	WorkspaceID       pgtype.UUID    `json:"workspace_id"`
	PickID            pgtype.UUID    `json:"pick_id"`
	StatDate          pgtype.Date    `json:"stat_date"`
	GmvAmount         pgtype.Numeric `json:"gmv_amount"`
	OrderCount        int32          `json:"order_count"`
	RefundAmount      pgtype.Numeric `json:"refund_amount"`
	EstCommission     pgtype.Numeric `json:"est_commission"`
	SettledCommission pgtype.Numeric `json:"settled_commission"`
	Currency          string         `json:"currency"`
	CreatedBy         pgtype.UUID    `json:"created_by"`
}

// `PUT /api/workbench/affiliate/daily` — one row per (pick, day). The body
// replaces the day: every measure is `excluded`, so a corrected report overwrites
// the previous value instead of merging two halves of the same day. `created_by`
// and `created_at` stay with the first write; `updated_at` moves.
func (q *Queries) UpsertAffiliateDaily(ctx context.Context, arg UpsertAffiliateDailyParams) (AffiliateDaily, error) {
	row := q.db.QueryRow(ctx, upsertAffiliateDaily,
		arg.WorkspaceID,
		arg.PickID,
		arg.StatDate,
		arg.GmvAmount,
		arg.OrderCount,
		arg.RefundAmount,
		arg.EstCommission,
		arg.SettledCommission,
		arg.Currency,
		arg.CreatedBy,
	)
	var i AffiliateDaily
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.PickID,
		&i.StatDate,
		&i.GmvAmount,
		&i.OrderCount,
		&i.RefundAmount,
		&i.EstCommission,
		&i.SettledCommission,
		&i.Currency,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
